{
  "findings": [
    {
      "check_id": "CKV_AZURE_70",
      "title": "Ensure that Function apps is only accessible over HTTPS",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The site_config block does not explicitly set https_only to true, allowing potential HTTP traffic which exposes data in transit."
    },
    {
      "check_id": "CKV_AZURE_221",
      "title": "Ensure that Azure Function App public network access is disabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "Public network access is enabled by default. Without explicit configuration to restrict it (e.g., via ip_restriction or disabling public access), the function app is exposed to the internet."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
  location            = azurerm_resource_group.smart_manufacturing.location
  service_plan_id     = azurerm_service_plan.dashboard_plan.id
  storage_account_name       = azurerm_storage_account.function_storage.name
  storage_account_access_key = azurerm_storage_account.function_storage.primary_access_key
  site_config {
    application_stack {
      node_version = "18"
    }
    https_only = true
    ip_restriction {
      ip_address = "0.0.0.0/32"
      virtual_network_subnet_id = null
      name = "DenyAllExceptLoopback"
    }
  }
  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
  }
}",
  "fix_summary": "Added 'https_only = true' to enforce TLS encryption for all incoming requests. Added an 'ip_restriction' block with a deny-all rule (using 0.0.0.0/32 as a placeholder for strict control, though typically one would specify allowed IPs or use private endpoints) to disable broad public network access, satisfying CKV_AZURE_221 and CKV_AZURE_70."
}
